-- products: the 80 foods FreshFeed gives advice for.
--
-- Built from the Produce Cold Storage & Postharvest Handling Technical Manual
-- (docs/produce-cold-storage-manual.pdf), with respiration rates from USDA Agriculture
-- Handbook 66 (2016) and storage life from Cantwell, UC Davis (2001).
--
--   fresh_produce  (§1)  storage group, temperature, RH, ethylene role, chilling sensitivity,
--                         respiration class and rates (mg CO2/kg·h at 0–25°C), storage life
--   dairy          (§2)  moisture, fat, pH, failure mode, storage protocol
--   bakery_snack   (§3)  moisture, fat, water activity, failure mode, packaging need
--   fermented      (§4)  pH, salt brine, chilled storage protocol
--   dried_produce        nuts, dates, dried fruit and vegetables (very low respiration)
--
-- Names are in English, Hindi and Marathi. respiration_estimated = true marks rows
-- where the class is an estimate (explained in respiration_source).
-- Public read-only.

create table if not exists public.products (
  id                     serial primary key,
  name                   text not null unique,
  hindi_name             text,
  gujarati_name          text,
  commodity_class        text not null
                         check (commodity_class in ('fresh_produce','dried_produce','dairy','bakery_snack','fermented')),
  category               text,
  storage_group_id       smallint references public.storage_groups (id),
  moisture_min           numeric,
  moisture_max           numeric,
  fat_min                numeric,
  fat_max                numeric,
  ph_min                 numeric,
  ph_max                 numeric,
  aw_min                 numeric,
  aw_max                 numeric,
  salt_min               numeric,
  salt_max               numeric,
  storage_temp_c_min     numeric,
  storage_temp_c_max     numeric,
  rh_min                 numeric,
  rh_max                 numeric,
  ethylene_role          text check (ethylene_role in ('producer','sensitive','producer_and_sensitive') or ethylene_role is null),
  chilling_sensitive     boolean,
  respiration_class      text check (respiration_class in ('very_low','low','moderate','high','very_high','extremely_high') or respiration_class is null),
  precooling_method      text,
  primary_failure        text,
  packaging_note         text,
  storage_protocol       text,
  shelf_life_note        text,
  data_notes             text,
  source                 text default 'Produce Cold Storage & Postharvest Handling Technical Manual',
  resp_rate_min          numeric,
  resp_rate_max          numeric,
  resp_rate_temp_c       numeric,
  resp_mg_0c             numeric,
  resp_mg_5c             numeric,
  resp_mg_10c            numeric,
  resp_mg_15c            numeric,
  resp_mg_20c            numeric,
  resp_mg_25c            numeric,
  respiration_source     text,
  respiration_estimated  boolean not null default false,
  marathi_name           text,
  storage_life_text      text,
  storage_life_min_days  integer,
  storage_life_max_days  integer,
  storage_life_source    text
);

create index if not exists products_storage_group_id_idx on public.products (storage_group_id);

alter table public.products enable row level security;

drop policy if exists "Public read products" on public.products;
create policy "Public read products" on public.products
  for select using (true);

on conflict (id) do nothing;

-- keep the id sequence ahead of the seeded rows
select setval(pg_get_serial_sequence('public.products', 'id'), greatest((select max(id) from public.products), 1));
